  signal instr_DAT_I   : std_logic_vector(31 downto 0) := (others => '0');
  signal instr_STB_O   : std_logic;
  signal instr_ACK_I   : std_logic := '0';
  signal instr_CYC_O   : std_logic;
  signal instr_CTI_O   : std_logic_vector(2 downto 0);
  signal instr_STALL_I : std_logic := '0';

  signal data_ADR_O   : std_logic_vector(31 downto 0);
  signal data_DAT_I   : std_logic_vector(31 downto 0) := (others => '0');
  signal data_DAT_O   : std_logic_vector(31 downto 0);
  signal data_WE_O    : std_logic;
  signal data_SEL_O   : std_logic_vector(3 downto 0);
  signal data_STB_O   : std_logic;
  signal data_ACK_I   : std_logic := '0';
  signal data_CYC_O   : std_logic;
  signal data_CTI_O   : std_logic_vector(2 downto 0);
  signal data_STALL_I : std_logic := '0';

  signal cycle_count       : integer := 0;
  signal instruction_count : integer := 0;
  signal halt_sim          : boolean := false;
  signal data_ack_reg      : std_logic := '0';
  signal timer_value       : std_logic_vector(63 downto 0) := (others => '0');

begin

  -- Clock generation
  clk_gen: process
  begin
    while not halt_sim loop
      clk <= '0';
      wait for CLK_PERIOD / 2;
      clk <= '1';
      wait for CLK_PERIOD / 2;
    end loop;
    wait;
  end process clk_gen;

  -- Reset process
  reset_gen: process
  begin
    reset <= '1';
    wait for CLK_PERIOD * 5;
    reset <= '0';
    wait;
  end process reset_gen;

  -- Orca core instantiation
  dut: entity work.orca
    generic map (
      REGISTER_SIZE          => 32,
      RESET_VECTOR           => X"00000000",
      INTERRUPT_VECTOR       => X"00000000",
      MAX_IFETCHES_IN_FLIGHT => 1,
      BTB_ENTRIES            => 0,
      MULTIPLY_ENABLE        => 1,
      DIVIDE_ENABLE          => 1,
      SHIFTER_MAX_CYCLES     => 32,
      ENABLE_EXCEPTIONS      => 1,
      PIPELINE_STAGES        => 5,
      VCP_ENABLE             => 0,
      ENABLE_EXT_INTERRUPTS  => 0,
      POWER_OPTIMIZED        => 0,
      FAMILY                 => "GENERIC",
      LOG2_BURSTLENGTH       => 4,
      AXI_ID_WIDTH           => 2,
      AVALON_AUX             => 0,
      LMB_AUX                => 0,
      WISHBONE_AUX           => 1,
      AUX_MEMORY_REGIONS     => 1,
      AMR0_ADDR_BASE         => X"00000000",
      AMR0_ADDR_LAST         => X"FFFFFFFF",
      AMR0_READ_ONLY         => 0,
      UC_MEMORY_REGIONS      => 0,
      ICACHE_SIZE            => 0,
      DCACHE_SIZE            => 0,
      DATA_REQUEST_REGISTER  => 0
    )
    port map (
      clk   => clk,
      reset => reset,
      timer_value => timer_value,

      instr_ADR_O   => instr_ADR_O,
      instr_DAT_I   => instr_DAT_I,
      instr_STB_O   => instr_STB_O,
      instr_ACK_I   => instr_ACK_I,
      instr_CYC_O   => instr_CYC_O,
      instr_CTI_O   => instr_CTI_O,
      instr_STALL_I => instr_STALL_I,

      data_ADR_O   => data_ADR_O,
      data_DAT_I   => data_DAT_I,
      data_DAT_O   => data_DAT_O,
      data_WE_O    => data_WE_O,
      data_SEL_O   => data_SEL_O,
      data_STB_O   => data_STB_O,
      data_ACK_I   => data_ACK_I,
      data_CYC_O   => data_CYC_O,
      data_CTI_O   => data_CTI_O,
      data_STALL_I => data_STALL_I
    );

  -- Combinational Wishbone Data slave signals: writes ACK immediately, reads ACK on next cycle
  data_ACK_I <= data_CYC_O and data_STB_O;

  -- Combinational data read
  d_comb_read: process(data_CYC_O, data_STB_O, data_WE_O, data_ADR_O, ram)
    variable d_idx : integer;
  begin
    if data_CYC_O = '1' and data_STB_O = '1' and data_WE_O = '0' then
      d_idx := to_integer(unsigned(data_ADR_O(15 downto 2)));
      if d_idx < RAM_WORDS then
        data_DAT_I <= ram(d_idx);
      else
        data_DAT_I <= (others => '0');
      end if;
    else
      data_DAT_I <= (others => '0');
    end if;
  end process;

  mem_proc: process(clk)
    variable i_idx : integer;
    variable d_idx : integer;
    variable l     : line;
    variable c     : character;
  begin
    if rising_edge(clk) then
      if reset = '1' then
        instr_ACK_I  <= '0';
        cycle_count <= 0;
        instruction_count <= 0;
        timer_value <= (others => '0');
      else
        cycle_count <= cycle_count + 1;
        timer_value <= std_logic_vector(unsigned(timer_value) + 1);

        if (cycle_count mod 10000 = 0) then
          report "Cycle: " & integer'image(cycle_count) & " Instructions: " & integer'image(instruction_count) & " PC: " & to_hstring(instr_ADR_O);
        end if;

        -- Instruction Wishbone Slave (clean 1-cycle synchronous pipelined response)
        if (instr_CYC_O = '1' and instr_STB_O = '1') then
          if instr_ADR_O = X"00000038" or instr_ADR_O = X"00000AFC" then
            report "TRAP TAKEN: PC=" & to_hstring(instr_ADR_O) & " at cycle " & integer'image(cycle_count);
          end if;
          if instr_ADR_O = X"00000CA0" or instr_ADR_O = X"00000CA4" or instr_ADR_O = X"00000CC4" then
            report "TRAP HANG: PC=" & to_hstring(instr_ADR_O) & " at cycle " & integer'image(cycle_count);
          end if;
          i_idx := to_integer(unsigned(instr_ADR_O(15 downto 2)));
          if i_idx < RAM_WORDS then
            instr_DAT_I <= ram(i_idx);
          else
            instr_DAT_I <= (others => '0');
          end if;
          instr_ACK_I <= '1';
          instruction_count <= instruction_count + 1;
        else
          instr_ACK_I <= '0';
        end if;

        -- Data Wishbone writes
        if (data_CYC_O = '1' and data_STB_O = '1' and data_WE_O = '1') then
          if unsigned(data_ADR_O) >= X"10000000" then
            report "MMIO WRITE: addr=" & to_hstring(data_ADR_O) & " data=" & to_hstring(data_DAT_O);
          end if;
          -- Check MMIO UART write (e.g. tohost or UART at 0x20000000 or 0x80000000)
          if data_ADR_O = X"20000000" or data_ADR_O = X"80000000" then
            c := character'val(to_integer(unsigned(data_DAT_O(7 downto 0))));
            report "UART OUT: " & c;
            write(l, c);
            writeline(output, l);
          elsif data_ADR_O = X"20000004" then
            -- tohost / exit signal
            report "TOHOST exit requested: " & integer'image(to_integer(unsigned(data_DAT_O(30 downto 0))));
            report "Orca simulation finished successfully!";
            report "Total execution cycles: " & integer'image(cycle_count);
            report "Total instructions executed: " & integer'image(instruction_count);
            halt_sim <= true;
          else
            d_idx := to_integer(unsigned(data_ADR_O(15 downto 2)));
            if d_idx < RAM_WORDS then
              if data_SEL_O(0) = '1' then
                ram(d_idx)(7 downto 0) <= data_DAT_O(7 downto 0);
              end if;
              if data_SEL_O(1) = '1' then
                ram(d_idx)(15 downto 8) <= data_DAT_O(15 downto 8);
              end if;
              if data_SEL_O(2) = '1' then
                ram(d_idx)(23 downto 16) <= data_DAT_O(23 downto 16);
              end if;
              if data_SEL_O(3) = '1' then
                ram(d_idx)(31 downto 24) <= data_DAT_O(31 downto 24);
              end if;
            end if;
          end if;
        end if;

        -- Termination condition: TOHOST write or timeout
        if cycle_count > 1500000 then
          report "Simulation timeout reached!";
          halt_sim <= true;
        end if;
      end if;
    end if;
  end process mem_proc;

end architecture sim;
